func validateUsageJSONValue(path string, value any, description string) error {
	field := path
	if field == "" {
		field = "$payload"
	}
	if value == nil {
		return invalidGeneratedFieldTypeError(field, "object", "null", description)
	}
	typed, ok := value.(map[string]any)
	if !ok {
		return invalidGeneratedFieldTypeError(field, "object", decodedJSONType(value), description)
	}
	keys := make([]string, 0, len(typed))
	for key := range typed {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		switch key {
		case "input_tokens":
			if err := validateUsageJSONValue2(
				generatedJSONChildPath(path, key, false),
				typed[key], "Reported input tokens, when supplied.",
			); err != nil {
				return err
			}
		case "output_tokens":
			if err := validateUsageJSONValue3(
				generatedJSONChildPath(path, key, false),
				typed[key], "Reported output tokens, when supplied.",
			); err != nil {
				return err
			}
		default:
			return unknownJSONFieldError(path, key, []string{
				"input_tokens",
				"output_tokens",
			})
		}
	}
	return nil
}

